@Injectable()
export class JwtStrategy extends PassportStrategy(Strategy) {
  constructor(config: ConfigService) {
    super({
      jwtFromRequest: ExtractJwt.fromAuthHeaderAsBearerToken(),
      ignoreExpiration: true,        // BUG: expired tokens are accepted
      secretOrKey: 'dev-secret-123', // BUG: hardcoded, != JwtModule's signing secret
    });
  }

  async validate(payload: { sub: string; username: string }) {
    return { userId: payload.sub, username: payload.username };
  }
}

model.en:
super({
  jwtFromRequest: ExtractJwt.fromAuthHeaderAsBearerToken(),
  ignoreExpiration: false,                                  // enforce the exp claim
  secretOrKey: config.getOrThrow<string>('JWT_SECRET'),     // SAME secret JwtModule signs with
});

Why: (1) ignoreExpiration must be false (the default) so Passport rejects tokens past their exp — leaving it true means a stolen token never expires from verification's point of view, defeating the whole short-TTL strategy. (2) secretOrKey must be the exact secret used in JwtModule's signOptions/secret. If it differs, signature verification fails for every legitimate token; if a stale hardcoded value happens to match an old signing key, you keep validating tokens minted under a key you meant to retire. Pull it from ConfigService.getOrThrow so the same env value feeds both sign and verify, and a missing secret fails fast at boot rather than silently using a placeholder.

